#!/usr/bin/env python3
"""Print a PR body (read from stdin) without the "Generated by" footer the
Claude cloud GitHub connector appends after the hook has already checked it.

Only the exact footer at the very end is removed; anything else is untouched.
"""
import re
import sys

FOOTER = re.compile(
    r"(?:\r?\n)*(?:---\r?\n)?"
    r"_Generated by \[Claude Code\]\(https://claude\.ai/code[^)\s]*\)_\s*\Z"
)

if __name__ == "__main__":
    # Bytes, not text mode, so CRLF bodies come back byte-for-byte when unchanged.
    body = sys.stdin.buffer.read().decode()
    sys.stdout.buffer.write(FOOTER.sub("", body).encode())
